select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987107001,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Stephen Hawking en Leonard Mlodinow geven een beknopte inleiding tot vragen over ruimte, tijd en het ontstaan van het heelal. Zij leggen onder meer relativiteit, gekromde ruimte en kwantumtheorie uit voor een algemeen publiek. Deze bewerking van Hawkings eerdere boek Het heelal ordent de onderwerpen opnieuw en betrekt er latere ontwikkelingen in de natuurkunde bij. Het doel is niet alleen minder tekst, maar ook een toegankelijker uitleg van begrippen die in het oorspronkelijke boek veel lezers voor vragen stelden.","work_id":987107001,"evidence":[{"note":"Reuse current exactDutch paperback9789035141704. Work2392alreadycorrectlyBriefer2005, separate86isBrief1988. Hawking+Mlodinow joint authorship verified; no relink/merge or original-year mutation. Corrected earlier ambiguous predecessor reference in original Dutch draft.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p39759433X","http://data.bibliotheken.nl/id/nbt/p38992461X","http://data.bibliotheken.nl/id/nbt/p369866568","http://data.bibliotheken.nl/id/nbt/p425755894"],"reference":"work:2392","checked_at":"2026-11-02T18:44:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-amendment-006.json","sources":["https://www.penguinrandomhouse.com/books/77009/a-briefer-history-of-time-by-stephen-hawking-with-leonard-mlodinow/","https://www.deslegte.com/een-korte-geschiedenis-van-de-tijd-138009/","https://www.penguinrandomhouse.com/books/77010/a-brief-history-of-time-by-stephen-hawking/","https://openlibrary.org/works/OL1892618W","https://data.bibliotheken.nl/id/nbt/p39759433X","https://data.bibliotheken.nl/id/nbt/p38992461X","https://data.bibliotheken.nl/id/nbt/p369866568","https://data.bibliotheken.nl/id/nbt/p425755894"]},{"type":"cover_front_review"